function longestCommonPrefix(strs) {
  if (!strs.length) return '';
  let pre = strs[0];
  for (const s of strs) {
    while (!s.startsWith(pre)) pre = pre.slice(0, -1);
    if (!pre) return '';
  }
  return pre;
}

