function combinationSum(c, target) {
  const out = [];
  const dfs = (i, cur, sum) => {
    if (sum === target) { out.push([...cur]); return; }
    if (sum > target || i === c.length) return;
    cur.push(c[i]); dfs(i, cur, sum + c[i]); cur.pop();
    dfs(i + 1, cur, sum);
  };
  dfs(0, [], 0);
  return out;
}

