function longestPalindrome(s) {
  let start = 0, max = 0;
  const expand = (l, r) => {
    while (l >= 0 && r < s.length && s[l] === s[r]) { if (r - l + 1 > max) { max = r - l + 1; start = l; } l--; r++; }
  };
  for (let i = 0; i < s.length; i++) { expand(i, i); expand(i, i + 1); }
  return s.slice(start, start + max);
}

