function isValid(s) {
  const st = []; const m = { ')': '(', ']': '[', '}': '{' };
  for (const c of s) {
    if (c in m) { if (st.pop() !== m[c]) return false; }
    else st.push(c);
  }
  return st.length === 0;
}

