  const adj = Array.from({ length: n }, () => []);
  const indeg = new Array(n).fill(0);
  for (const [a, b] of pre) { adj[b].push(a); indeg[a]++; }
  const q = []; for (let i = 0; i < n; i++) if (!indeg[i]) q.push(i);
  let seen = 0;
