function trap(height) {
  let l = 0, r = height.length - 1, lw = 0, rw = 0, water = 0;
  while (l < r) {
    if (height[l] < height[r]) { lw = Math.max(lw, height[l]); water += lw - height[l++]; }
    else { rw = Math.max(rw, height[r]); water += rw - height[r--]; }
  }
  return water;
}

