function countPrimes(n) {
  const s = new Uint8Array(n).fill(1);
  let count = 0;
  for (let i = 2; i < n; i++) {
    if (s[i]) {
      count++;
      for (let j = i * i; j < n; j += i) s[j] = 0;
    }
  }
  return count;
}

