function levelOrder(root) {
  const out = []; if (!root) return out;
  const q = [root];
  while (q.length) {
    const n = q.length, level = [];
    for (let i = 0; i < n; i++) {
      const node = q.shift(); level.push(node.val);
      if (node.left) q.push(node.left);
      if (node.right) q.push(node.right);
    }
    out.push(level);
  }
  return out;
}

