class MinStack {
  constructor() { this.a = []; this.m = []; }
  push(x) { this.a.push(x); this.m.push(this.m.length ? Math.min(x, this.m.at(-1)) : x); }
  pop() { this.a.pop(); this.m.pop(); }
  top() { return this.a.at(-1); }
  getMin() { return this.m.at(-1); }
}

