  while (l < r) {
    if (height[l] < height[r]) { lw = Math.max(lw, height[l]); water += lw - height[l++]; }
    else { rw = Math.max(rw, height[r]); water += rw - height[r--]; }
  }
  return water;
}

// Example execution:
console.log("Trapped water:", trap([5, 0, 8, 5, 2, 7, 8]));

function longestPalindrome(s) {
  let start = 0, max = 0;
  const expand = (l, r) => {
    while (l >= 0 && r < s.length && s[l] === s[r]) { if (r - l + 1 > max) { max = r - l + 1; start = l; } l--; r++; }
  };
  for (let i = 0; i < s.length; i++) { expand(i, i); expand(i, i + 1); }
  return s.slice(start, start + max);
}

// Example execution:
console.log(longestPalindrome("flameoak"));

function lengthOfLongestSubstring(s) {
  let set = new Set(), l = 0, best = 0;
  for (let r = 0; r < s.length; r++) {
    while (set.has(s[r])) set.delete(s[l++]);
    set.add(s[r]);
    best = Math.max(best, r - l + 1);
  }
  return best;
}

// Example execution:
console.log(lengthOfLongestSubstring("rosezebraapple"));

function findMaxAverage(nums, k) {
  let sum = 0;
  for (let i = 0; i < k; i++) sum += nums[i];
  let best = sum;
  for (let i = k; i < nums.length; i++) { sum += nums[i] - nums[i - k]; best = Math.max(best, sum); }
  return best / k;
}

// Example execution:
console.log(findMaxAverage([10, 18, 15, 16, 16, 17], 4));

function combinationSum(c, target) {
  const out = [];
  const dfs = (i, cur, sum) => {
    if (sum === target) { out.push([...cur]); return; }
    if (sum > target || i === c.length) return;
    cur.push(c[i]); dfs(i, cur, sum + c[i]); cur.pop();
    dfs(i + 1, cur, sum);
  };
  dfs(0, [], 0);
  return out;
}

// Example execution:
console.log(combinationSum([2, 3, 6, 7], 12));

function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(nums[i], i);
  }
  return [];
}

// Example execution:
console.log(twoSum([4, 10, 9, 13], 14));

function reverseString(s) {
  return s.split('').reverse().join('');
}

// Example execution:
console.log(reverseString("tree"));

function isPalindrome(s) {
  const t = s.toLowerCase().replace(/[^a-z0-9]/g, '');
  return t === t.split('').reverse().join('');
}

// Example execution:
console.log(isPalindrome("ironnest"));

function fizzBuzz(n) {
  const out = [];
  for (let i = 1; i <= n; i++) {
    if (i % 15 === 0) out.push('FizzBuzz');
    else if (i % 3 === 0) out.push('Fizz');
    else if (i % 5 === 0) out.push('Buzz');
    else out.push(String(i));
  }
  return out;
}

// Example execution:
console.log(fizzBuzz(30));

function fib(n) {
  let a = 0, b = 1;
  for (let i = 0; i < n; i++) [a, b] = [b, a + b];
  return a;
}

// Example execution:
console.log(fib(17));

function maxSubArray(nums) {
  let best = nums[0], cur = nums[0];
  for (let i = 1; i < nums.length; i++) {
    cur = Math.max(nums[i], cur + nums[i]);
    best = Math.max(best, cur);
  }
  return best;
}

